<template><view class="page"><text class="title">我的未来职业探索清单</text><text class="hint">这些是你主动关注的职业（清单上限 6/6）</text><view class="section-title">我想进一步了解（{{items.length}}/6）</view><view v-for="item in items" :key="item.careerId" class="item"><view><text class="item-name">{{item.careerName}}</text><text class="item-intro">{{item.oneLineIntro || ''}}</text></view><button v-if="!readOnly" hover-class="button-hover" size="mini" @click="remove(item)">删除</button></view><text v-if="!items.length" class="empty">还没有加入探索清单的职业</text><button v-if="!readOnly" hover-class="button-hover" @click="showOther = !showOther">{{showOther ? '收起其他职业' : '添加其他职业'}}</button><view v-if="showOther && !readOnly" class="other-panel"><input v-model="keyword" class="search" placeholder="搜索职业名称" /><view v-for="item in filteredCareers" :key="item.careerId" class="other-row"><view><text>{{item.careerName}}</text><text class="other-intro">{{item.oneLineIntro || ''}}</text></view><button v-if="!isAdded(item)" type="primary" hover-class="button-hover" size="mini" @click="add(item)">+</button><text v-else class="added">已加入</text></view></view><view class="today"><text class="section-title">今日认识（已查看但未加入的职业）</text><text class="today-count">{{todayViewed.length}} 个</text><text v-for="item in todayViewed" :key="item.careerId" class="today-item">{{item.careerName}}</text></view><text class="limit-tip">最多可加入6个职业，达到上限前需删除后再添加。</text><button v-if="!readOnly" type="primary" hover-class="button-hover" @click="finish">确认我的探索清单</button><button v-else type="primary" hover-class="button-hover" @click="download">下载探索清单 PDF</button><button hover-class="button-hover" @click="continueExplore">继续探索更多职业</button><text v-if="!items.length" class="empty-tip">没关系，今天不一定要找到“最想探索的职业”。你刚刚已经认识了一个职业，未来还可以继续探索更多可能。</text></view></template>
<script>
import { getExploration, getCatalog, removeExplorationItem, addExplorationItem, finishRecord, downloadReportPdf, userMessage } from '@/api/zycck'
export default { data: () => ({ recordId: '', instanceId: '', gameId: '', items: [], allCareers: [], viewedIds: [], readOnly: false, showOther: false, keyword: '' }), computed: { filteredCareers() { const key = this.keyword.trim(); return this.allCareers.filter(x => !key || String(x.careerName).includes(key)) }, todayViewed() { const added = this.items.map(x => String(x.careerId)); return this.allCareers.filter(x => this.viewedIds.some(id => String(id) === String(x.careerId)) && !added.includes(String(x.careerId))) } }, onLoad(o) { Object.assign(this, { recordId: o.recordId || '', instanceId: o.instanceId || '', gameId: o.gameId || '', readOnly: o.readOnly === '1' }); this.load() }, methods: { async load() { try { const [r, c] = await Promise.all([getExploration(this.recordId), getCatalog({ instanceId: this.instanceId, gameId: this.gameId })]); const d = r.data || {}; this.items = d.items || d.explorationItems || []; const raw = d.viewedCareerIds || []; this.viewedIds = Array.isArray(raw) ? raw : JSON.parse(raw || '[]'); const rows = (c.data || {}).careers || []; this.allCareers = rows.filter(x => String(x.hasQuestion) !== '1').map(x => ({ ...x, careerId: x.careerId || x.careerQuestionId, careerName: x.careerName || x.name || x.title })) } catch (e) { uni.showToast({ title: userMessage(e, '探索清单加载失败，请重试'), icon: 'none' }) } }, isAdded(i) { return this.items.some(x => String(x.careerId) === String(i.careerId)) }, async add(i) { if (this.items.length >= 6) return uni.showToast({ title: '探索清单最多添加6个职业', icon: 'none' }); try { await addExplorationItem(this.recordId, i.careerId); await this.load() } catch (e) { uni.showToast({ title: userMessage(e, '加入清单失败，请重试'), icon: 'none' }) } }, async remove(i) { try { await removeExplorationItem(this.recordId, i.careerId); await this.load() } catch (e) { uni.showToast({ title: userMessage(e, '移除清单失败，请重试'), icon: 'none' }) } }, async finish() { try { await finishRecord(this.recordId); this.readOnly = true; uni.showToast({ title: '探索清单已确认', icon: 'success' }) } catch (e) { uni.showToast({ title: userMessage(e, '请先查看至少一个职业'), icon: 'none' }) } }, async download() { try { uni.showLoading({ title: '生成 PDF' }); const r = await downloadReportPdf({ recordId: this.recordId }); const path = r.tempFilePath || r.filePath; if (path) uni.openDocument({ filePath: path, showMenu: true, fileType: 'pdf' }); else throw new Error('PDF 下载失败') } catch (e) { uni.showToast({ title: userMessage(e, 'PDF 下载失败，请稍后重试'), icon: 'none' }) } finally { uni.hideLoading() } }, continueExplore() { uni.redirectTo({ url: `/pages/zycck/categories?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}` }) } } }
</script>
<style scoped>.page{padding:48rpx 36rpx;background:#f5f7fb;min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column}.title{display:block;font-size:42rpx;font-weight:700;text-align:center;color:#1a2c4a}.hint{display:block;text-align:center;color:#64748b;margin:16rpx 0 28rpx}.section-title{display:block;font-size:31rpx;font-weight:700;color:#27364a;margin:20rpx 0}.item,.other-row{display:flex;align-items:center;justify-content:space-between;background:#fff;padding:24rpx;border-radius:14rpx;margin:10rpx 0}.item-name{display:block;font-size:30rpx}.item-intro,.other-intro{display:block;color:#8a94a6;font-size:23rpx;margin-top:8rpx}.empty{text-align:center;color:#9aa3af;padding:24rpx}.other-panel{margin-top:16rpx}.search{background:#fff;border-radius:12rpx;padding:20rpx 24rpx;margin-bottom:10rpx}.other-row text:first-child{font-size:28rpx}.added{color:#42a868;font-size:25rpx}.today{margin-top:28rpx;padding:24rpx;background:#fff;border-radius:14rpx}.today .section-title{display:inline-block;margin:0 14rpx 12rpx 0}.today-count{color:#d97745}.today-item{display:block;color:#4b5563;font-size:27rpx;padding:8rpx 0}.limit-tip,.empty-tip{display:block;color:#8a94a6;font-size:24rpx;line-height:1.6;margin:20rpx 0;text-align:center}.button-hover{opacity:.8;transform:scale(.98)}button{margin-top:16rpx}</style>
